content.text:
Now game.js. Let's write in parts maybe. It's long. Need be careful.

Structure:

1. imports, constants, state.
2. DOM refs.
3. utils (sleep, shuffle, esc?).
4. player/deck/card creation.
5. G API functions.
6. validation.
7. turn lifecycle.
8. actions (play, act, attack, direct, end).
9. AI.
10. rendering.
11. events.
12. audio/fx.
13. init.

Let's implement thoroughly.

Constants:
```
const SIDE = {player:'player', enemy:'enemy'};
const LP_MAX=3000;
const HAND_START=5;
```

State object reset:
```
let S = makeState();
function makeState() {
 return {
  started:false, over:false, active:'player', turnSerial:0, busy:false,
  players:{ player: createPlayer('player','あなた','光'), enemy: createPlayer('enemy','ノクス','冥') },
  log:[], selectedUid:null, attackerUid:null, removals:[], fx:[], enterUids:new Set(),
  intro:true, modalOpen:false, sound:true, result:null,
  displayLp:{player:LP_MAX,enemy:LP_MAX}, lpTweens:{}, aiToken:0, bannerTimer:null, logSeq:0
 };
}
```
But createPlayer uses card arrays. define before.

`createPlayer(side,name,mark)` returns {side,name,mark,lp,maxLp,deck,hand,grave,big:Array(6).fill(null),small:Array(6).fill(null),summonUsed:0,setUsed:0,extraSummons:0,ward:0,skipDraw:false,turnsTaken:0,stats:{summons:0,acts:0,damageDealt:0}}.

`makeCard(defId, owner)`: uid `c${++uidSeq}`. Global uidSeq outside S to avoid resetting collisions (DOM not persistent after reset but okay). Include mods=[], acted=false, stunned=false, summonedSerial=-99, zone=null, index=null, destroying=false.

`buildDeck(side)`: DECK_LIST map, shuffle.

Shuffle Fisher-Yates.

Log: `addLog(text, side='system', kind='')`; `S.log.push({text, side, kind, t:...}); if >50 shift`. Render later. For AI logs, side 'enemy'.

Card lookup:
```
function locate(uid) {
 for (const side of ['player','enemy']) {
  const p=S.players[side];
  for (const zone of ['big','small']) for (let i=0;i<6;i++) if (p[zone][i]?.uid===uid) return {side,zone,index:i,card:p[zone][i]};
  const hi=p.hand.findIndex(c=>c.uid===uid); if(hi>=0) return {side,zone:'hand',index:hi,card:p.hand[hi]};
 }
 return null;
}
function findCard(uid){ return locate(uid)?.card ?? null; }
```
Grave not selectable.

G API functions:

```
const G = {
 other, player: side=>S.players[side],
 damage(side, amount, kind='act', anchor=null) { ... },
 heal,
 draw,
 destroy,
 destroyAllRelics,
 bounce,
 stun,
 ward,
 skipDraw,
 extraSummon,
 refresh,
 mod,
 effAtk,
 effGuard,
 hasMod,
 monsters,
 relics,
 highestAtk,
 highestGuard,
 actedMonsters,
 emptyBig,
 emptySmall,
 graveMonsters,
 revive,
 summonToken,
 log: addLog
}
```

Damage:
```
const p=S.players[side]; const actual=Math.min(p.lp, Math.max(0,Math.round(amount)));
if (!actual) return;
p.lp-=actual;
if (kind==='act' && side!==S.active?) stats? Track dealer? For stats.
S.fx.push({type:'damage', side, amount:actual, kind, anchor: anchor || null});
addLog(`${sideLabel(side)}に${actual}ダメージ${kind==='cost'?'（コスト）':''}`, side, kind==='cost'?'cost':'damage');
```
But logging every damage plus card act logs might be noisy; okay, clear record. `sideLabel`: side==='player'?'あなた':'ノクス'. Use in logs.

LP costs message "700LPを支払った" instead of damage? Could special-case cost: log "700LPを支払った". FX float `-700`. Do:
```
if kind==='cost' addLog(`${label}は${actual}LPを支払った`, ...)
else addLog(`${label}に${actual}ダメージ`, ...)
```
For self damage "自分は300ダメージ" etc. Fine.

Heal:
```
const actual = min(max-lp, round(amount)); if(!actual) return; p.lp+=actual; fx heal; log.
```

Draw:
```
function draw(side,n) {
 const p=S.players[side];
 for (...) {
  if (!p.deck.length) recycle(p);
  if (!p.deck.length) break;
  const c=p.deck.pop(); c.zone=null; c.index=null; p.hand.push(c); S.enterUids.add(c.uid);
  addLog(`${label}は1枚ドロー`, side, 'draw');
 }
}
```
Recycle:
```
const dead=p.grave.splice(0); p.deck.push(...dead); shuffle(p.deck); addLog(`${label}の墓地を山札に戻した`, side,'system');
```
Log "1枚ドロー" for each; maybe consolidate? Simplify each.

Destroy:
```
if (!card || card.destroying || !card.zone) return;
card.destroying=true;
card.removal='destroy';
S.removals.push(card);
S.fx.push({type:'destroy', card});
addLog(`${label}の「${name}」を破壊`, other(card.owner)?...);
```
Log side of effect? Use `side` param default 'system'. Simpler: log `「name」が破壊された` side = card.owner, kind 'destroy'. Then performAct logs card name already. Fine.

Bounce:
```
card.destroying=true; card.removal='bounce'; S.removals.push(card); log.
```

Settle removals:
```
async function settleRemovals() {
 if (!S.removals.length) return;
 renderAll();
 await sleep(420);
 const list=S.removals.splice(0);
 for (const card of list) {
   const p=S.players[card.owner];
   if (card.zone) {
     const arr=p[card.zone];
     if (arr[card.index]===card) arr[card.index]=null;
   }
   card.destroying=false;
   card.zone=null; card.index=null; card.mods=[]; card.acted=false; card.stunned=false;
   if (card.removal==='bounce') { p.hand.push(card); addLog(`「${name}」が手札に戻った`, card.owner,'bounce'); S.enterUids.add(card.uid); }
   else if (!CARD_DEFS[card.defId].token) { p.grave.push(card); }
   card.removal=null;
 }
 S.removals=[];
 renderAll();
}
```
Important: if card destroyed while in hand? no.

Mods cleanup:
```
function cleanupMods(serial) {
 for side... for zones ... c.mods = c.mods.filter(m => m.untilSerial == null || serial < m.untilSerial);
}
```
At endTurn call `cleanupMods(S.turnSerial)`? If duration end set untilSerial = current serial, condition serial < untilSerial false → removed. Good. At begin turn after increment, also removes. For nextOwner untilSerial=current+2; at begin owner next (current+2), condition serial<until false → removed. Good.
Need mods on cards in hand? Buffed card bounced? Bounce clears mods on removal. Fine. Token etc.

Mod:
```
function mod(card, spec) {
 const untilSerial = spec.duration === 'end' ? S.turnSerial : spec.duration === 'nextOwner' ? S.turnSerial + 2 : null;
 card.mods.push({kind:spec.kind, value:spec.value||0, untilSerial, src:...});
}
```
`effAtk = card.atk + sum(kind==='atk')`; guard similarly.

`refresh(card)`: card.acted=false; card.stunned=false? Ring refreshes acted monster; if stunned, still shouldn't act. `actedMonsters` filters !stunned? Stunned cards are acted at refresh. If ring used during same turn after stun? Stun set on opponent during their turn; at their refresh set acted. Ring could refresh it, allowing action despite stun. Should stun persist. Check `actedMonsters` only cards with acted && !stunned. And refresh sets acted=false but leaves stunned; render might show. At owner refresh, stunned→acted. Fine.

`stun(card)`: card.stunned=true; if the card is already acted, next turn acted again. Good.

`summonToken(side)`:
```
const idx=emptyBig; if idx<0 return;
const c=makeCard('bloomtoken', side); p.big[idx]=c; c.zone='big'; c.index=idx; c.summonedSerial=S.turnSerial; S.enterUids.add(c.uid); log special summon.
```
`revive(side)`:
```
const grave=p.grave.filter(c=>CARD_DEFS[c.defId].kind==='monster' && !def.token);
if none return;
const target=grave.sort(eff? base atk desc)[0];
remove from grave; idx=emptyBig; place; summonedSerial=S.turnSerial; acted=false; mods=[]; enter.
```
Sort by base atk (buff cleared).
`destroyAllRelics`: iterate both small, call destroy (includes self). Ensure not already destroying.
`ward(side)`: p.ward++ ; log maybe card act logs.
`skipDraw`: p.skipDraw=true.
`extraSummon`: p.extraSummons++.

Validation:
```
function actReason(card) {
 if (S.over) return 'デュエルは終了しています';
 if (!S.started) return 'デュエルが始まっていません';
 if (S.busy) return '処理中です';
 if (S.modalOpen) return 'ルールを閉じてください';
 if (card.owner!==S.active) return '相手のターンです';
 if (card.owner!=='player') return null; // AI internal
 if (card.acted) return 'このターンは行動済みです';
 const d=CARD_DEFS[card.defId];
 if (d.noAct) return 'アクトを持ちません';
 return d.canAct(G,card) || null;
}
```
For AI, `executeAct` checks separately: acted, canAct. Need ward handled.

Play reason:
```
function playReason(card) {
 if (!S.started||S.over) ...
 if (S.busy)...
 if (S.modalOpen)...
 if (S.active!=='player')...
 if (card.owner!=='player')...
 const d=...
 if (d.token)...
 if (d.kind==='monster') { if (p.summonUsed >= 1+p.extraSummons) return '召喚権を使い切りました'; if (emptyBig<0) return 'BIGゾーンが埋まっています'; }
 else { if(p.setUsed>=1) return '設置権を使い切りました'; if(emptySmall<0) return 'SMALLゾーンが埋まっています'; }
 return null;
}
```
Extra summon logic: summonUsed starts 0; limit 1 + extra. Hayate act sets extraSummons=1 after summonUsed maybe 1, allowing another. If extra summon granted before summon, limit 2. Good.

`playCard(card, index)`:
- if reason toast.
- Determine zone type; index from clicked slot if valid and empty else first empty.
- remove from hand.
- place.
- if monster: summonUsed++; summonedSerial=current; stats.
- relic: setUsed++; summonedSerial=null.
- add log, sfx summon/set, enterUids.
- clear selection.
- render + flush fx.
- If monster has "summon" effect? no.

Important: When a card is set (relic), can act immediately. Yes. Also `acted=false`.
If placed on turn and relic acts same turn, consumed. Good.

Player activate:
```
async function playerActivate(card) {
 const reason=actReason(card); if(reason){toast(reason);return}
 S.busy=true; S.selectedUid=null; S.attackerUid=null; renderAll();
 await executeAct(card, 'player');
 S.busy=false; renderAll();
}
```
`executeAct(card)`:
```
const d=CARD_DEFS[card.defId];
const p=S.players[card.owner];
if (p.ward>0) {
 p.ward--;
 card.acted=true;
 addLog(`結界が「${d.name}」のアクトを無効化`, card.owner,'ward');
 sfx('negate');
 S.fx.push({type:'negate', card});
 renderAll(); await sleep(500); flushFx(); return;
}
card.acted=true;
const el=cardEl(card.uid); if(el) { el.classList.add('acting'); await sleep(180); }
sfx('act');
addLog(`${label}：${d.name}《${d.actName}》`, card.owner, 'act');
d.act(G,card, {S})? just G
// Some acts destroy self (vortex) or bounce self (hayate) -> card may be destroying; still fine.
renderAll();
await sleep(120);
await settleRemovals();
flushFx();
checkGameOver();
```
Wait card name for log d.name. ACT log should happen before effects? Effects log after. Fine.
If ward negates, does card still get acted? "アクトを無効化" — the act is negated, likely card still consumed. Yes, set acted true. Render shows.
AI should sometimes use ward-bait; okay.

Animations: add class 'acting' then sleep 160, but render before? Card element exists. Use WAAPI instead to pulse independent of render:
```
pulseCard(card.uid)
```
Using animations on element. Then no need class/sleep. Simpler:
```
sfx('act'); floatAct(card);
```
`pulseCard` animate transform scale 1→1.08→1, 260ms; not await. Then await 180 for feel.

For act effects that need target anchor, G.damage called without anchor → float near LP; for destroy, card ghost.

After d.act, renderAll, await settleRemovals, flushFx. If d.act destroyed enemy card, render shows `.destroying` then remove. Good.

`checkGameOver`: after LP reaches 0; if S.over return. Determine if both? Only one can hit 0 at a time due costs? Archive self damage could kill self if LP>500 then damage 500; if LP=501, leaves 1; can't die. Altar no. Simultaneous? no. Crystal. So single.
```
if (p.lp<=0) { S.over=true; S.result = p.side==='enemy'?'win':'lose'; ... setTimeout(showGameOver, 900) }
```
This function may be called multiple times; guard.

If player drops to 0 during AI, schedule gameover; AI loop checks `S.over`.

Attack functions:
`attackReason(attacker)`:
- started, not over, active, busy/modal, owner, monster, acted, summonedSerial===turnSerial → '召喚したターンは攻撃できません', stunned.
- If no valid targets? Enemies logic.
`validTargets(attacker)`:
```
const enemies=G.monsters(other).filter(c=>!c.destroying);
if (!enemies.length) return {direct:true, monsters:[]};
const direct=hasMod(attacker,'direct');
const taunts=enemies.filter(c=>hasMod(c,'taunt'));
return {direct, monsters: direct?enemies:(taunts.length?taunts:enemies)};
```
If taunt and direct? direct bypass; monsters all (or taunts only for non-direct; if direct but chooses monster, taunt still applies? If direct effect, can bypass but if attacking monster, taunt should force. Keep monsters=taunts when taunts exist even if direct, plus direct allowed.)
```
const targets = taunts.length ? taunts : enemies;
return {direct, monsters: targets};
```
Player attack target mode uses these.
If no enemies: direct true; attack button immediate.
If enemies and no direct and targets empty impossible.

`startAttack(attacker)`:
```
const reason=attackReason; if reason toast;
const v=validTargets(attacker);
if (!v.monsters.length && v.direct) { performAttack(attacker,null); }
else { S.attackerUid=attacker.uid; S.selectedUid=null; renderAll(); sfx('target'); }
```
If v.monsters and only one and no direct, still target mode (player choice not needed but preview helpful). Could auto-attack? No, let them confirm.

`performAttack(attacker, targetUidOrNull, {ai}={})`:
```
if (S.busy && !ai?)... // player wrapper sets busy; internal should allow.
const target = targetUid ? findCard(targetUid) : null;
// validate target belongs to valid list (player only)
if player and target invalid → toast.
S.busy=true; S.selectedUid=null; S.attackerUid=null; 
const aEl=cardElement(attacker.uid); const tEl=...
const aRect=aEl?.getBoundingClientRect(); const tRect=target? ... : lpRect(enemy)
if (aEl && tRect) {
 const dx=(tRect.left+tRect.width/2)-(aRect.left+aRect.width/2);
 const dy=(tRect.top+tRect.height/2)-(aRect.top+aRect.height/2);
 aEl.classList.add('attacking'); // optional
 aEl.animate([...],...)
}
sfx('attack');
await sleep(260);
attacker.acted=true;
const atkA=G.effAtk(attacker);
if (!target) {
 G.damage(other(attacker.owner), atkA, 'battle', lpAnchor(other));
 addLog(`「${name}」の直接攻撃`,...)
 spawnSlash(lpRect, '#ff6b6b');
} else {
 const atkD=G.effAtk(target);
 const aShield=has battleShield; dShield...
 if (atkA>atkD) {
   if(!dShield) G.destroy(target);
   G.damage(target.owner, atkA-atkD, 'battle', tRect);
 } else if (atkA<atkD) {
