/* ZONE XII — 六大六小の決闘 */

:root {
  --bg: #050811;
  --bg-2: #0a1224;
  --ink: #e9eefc;
  --muted: #8c9cc2;
  --gold: #e8c37a;
  --gold-2: #f8e6b8;
  --cyan: #6fe7ff;
  --red: #ff5f6d;
  --green: #8fffc8;
  --violet: #c8b6ff;
  --panel: rgba(11, 18, 34, 0.74);
  --panel-2: rgba(7, 12, 24, 0.88);
  --line: rgba(150, 180, 255, 0.16);
  --line-soft: rgba(150, 180, 255, 0.08);
  --font: 'IPAGothic', 'IPAPGothic', 'Hiragino Kaku Gothic ProN', 'Noto Sans JP', 'WenQuanYi Zen Hei', system-ui, sans-serif;
  --display: 'DejaVu Serif', 'Georgia', 'Times New Roman', serif;
  --hand-w: 106px;
  --hand-h: 150px;
}

* {
  box-sizing: border-box;
}

html,
body {
  height: 100%;
  margin: 0;
}

body {
  overflow: hidden;
  overscroll-behavior: none;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  -webkit-tap-highlight-color: transparent;
}

button {
  font-family: inherit;
  color: inherit;
  -webkit-tap-highlight-color: transparent;
  touch-action: manipulation;
}

button:focus-visible {
  outline: 2px solid var(--cyan);
  outline-offset: 2px;
}

#app {
  position: relative;
  height: 100vh;
  height: 100dvh;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  overflow: hidden;
}

/* ── backdrop ───────────────────────────────────────────── */

.backdrop {
  position: fixed;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  background:
    radial-gradient(ellipse 70% 50% at 50% -10%, rgba(45, 78, 150, 0.38), transparent 70%),
    radial-gradient(ellipse 55% 45% at 8% 68%, rgba(92, 47, 130, 0.22), transparent 70%),
    radial-gradient(ellipse 50% 45% at 92% 78%, rgba(20, 96, 112, 0.18), transparent 70%),
    linear-gradient(180deg, #080d1a 0%, #04070f 58%, #050811 100%);
}

.backdrop::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(120, 160, 255, 0.035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(120, 160, 255, 0.035) 1px, transparent 1px);
  background-size: 64px 64px;
  mask-image: radial-gradient(ellipse 70% 65% at 50% 50%, #000 20%, transparent 78%);
  -webkit-mask-image: radial-gradient(ellipse 70% 65% at 50% 50%, #000 20%, transparent 78%);
}

.backdrop::after {
  content: '';
  position: absolute;
  inset: 0;
  background:
    repeating-linear-gradient(0deg, rgba(255, 255, 255, 0.012) 0 1px, transparent 1px 3px),
    radial-gradient(ellipse 60% 60% at 50% 50%, transparent 45%, rgba(0, 0, 0, 0.42) 100%);
  pointer-events: none;
}

.rune-ring {
  position: absolute;
  left: 50%;
  top: 50%;
  width: min(92vmin, 860px);
  aspect-ratio: 1;
  transform: translate(-50%, -50%);
  border: 1px solid rgba(232, 195, 122, 0.11);
  border-radius: 50%;
  box-shadow: 0 0 60px rgba(80, 130, 255, 0.06) inset;
  animation: spin 90s linear infinite;
}

.rune-ring::before,
.rune-ring::after {
  content: '';
  position: absolute;
  inset: 7%;
  border: 1px dashed rgba(111, 231, 255, 0.09);
  border-radius: 50%;
}

.rune-ring::after {
  inset: 19%;
  border-style: solid;
  border-color: rgba(232, 195, 122, 0.06);
}

.ring-2 {
  width: min(58vmin, 560px);
  animation-direction: reverse;
  animation-duration: 64s;
  border-color: rgba(111, 231, 255, 0.08);
}

#stars {
  position: absolute;
  inset: 0;
}

#stars i {
  position: absolute;
  width: var(--s, 1px);
  height: var(--s, 1px);
  border-radius: 50%;
  background: #dce9ff;
  animation: twinkle var(--d, 5s) ease-in-out infinite;
  animation-delay: var(--delay, 0s);
  box-shadow: 0 0 5px rgba(160, 200, 255, 0.55);
}

@keyframes spin {
  to { transform: translate(-50%, -50%) rotate(360deg); }
}

@keyframes twinkle {
  0%, 100% { opacity: 0.12; }
  50% { opacity: 0.85; }
}

/* ── top bar ────────────────────────────────────────────── */

.topbar {
  position: relative;
  z-index: 8;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 12px;
  min-height: 54px;
  padding: max(7px, env(safe-area-inset-top)) 18px 5px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.brand-mark {
  flex: none;
  font-family: var(--display);
  font-size: 20px;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--gold-2);
  padding: 1px 7px 2px;
  border: 1px solid rgba(232, 195, 122, 0.45);
  border-radius: 4px;
  background: linear-gradient(180deg, rgba(232, 195, 122, 0.14), rgba(232, 195, 122, 0.03));
  box-shadow: 0 0 18px rgba(232, 195, 122, 0.12);
}

.brand-text {
  display: flex;
  flex-direction: column;
  min-width: 0;
  line-height: 1.1;
}

.brand-title {
  font-family: var(--display);
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.22em;
  color: #eef3ff;
}

.brand-sub {
  margin-top: 2px;
  font-size: 8px;
  letter-spacing: 0.26em;
  color: rgba(232, 195, 122, 0.78);
  white-space: nowrap;
}

.turn-pill {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 5px 12px;
  border: 1px solid var(--line);
  border-radius: 99px;
  background: rgba(6, 11, 22, 0.66);
  font-size: 9px;
  letter-spacing: 0.14em;
  color: var(--muted);
  white-space: nowrap;
  transition: border-color 0.3s, color 0.3s, box-shadow 0.3s;
}

.turn-pill.your-turn {
  border-color: rgba(232, 195, 122, 0.42);
  color: var(--gold-2);
  box-shadow: 0 0 22px rgba(232, 195, 122, 0.1);
}

.turn-pill.foe-turn {
  border-color: rgba(255, 95, 109, 0.34);
  color: #ffc0c7;
}

.turn-pill.over {
  border-color: rgba(255, 255, 255, 0.2);
  color: #d7dff2;
}

.turn-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--gold);
  box-shadow: 0 0 8px var(--gold);
}

.foe-turn .turn-dot {
  background: var(--red);
  box-shadow: 0 0 8px var(--red);
  animation: blink 1.1s infinite;
}

.turn-sep {
  opacity: 0.3;
}

.top-actions {
  display: flex;
  justify-content: flex-end;
  gap: 6px;
}

.icon-btn {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: rgba(10, 17, 32, 0.7);
  color: #c8d4ee;
  font-size: 13px;
  cursor: pointer;
  transition: border-color 0.2s, background 0.2s, color 0.2s, transform 0.2s;
}

.icon-btn:hover {
  border-color: rgba(232, 195, 122, 0.5);
  color: var(--gold-2);
  transform: translateY(-1px);
}

.icon-btn.off {
  color: #5d6b8b;
}

/* ── arena layout ───────────────────────────────────────── */

.arena-wrap {
  position: relative;
  z-index: 3;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 268px;
  gap: 14px;
  min-height: 0;
  padding: 0 18px;
}

.arena {
  position: relative;
  display: grid;
  grid-template-rows: minmax(0, 1fr) auto minmax(0, 1fr) auto;
  gap: 0;
  width: 100%;
  max-width: 980px;
  min-height: 0;
  margin: 0 auto;
  padding: 2px 0;
}

.side {
  display: flex;
  flex-direction: column;
  gap: 6px;
  width: 100%;
  min-height: 0;
}

.enemy-side {
  justify-content: flex-start;
}

.player-side {
  justify-content: flex-end;
}

.board {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
  min-height: 0;
  padding: 2px 3px;
  border-radius: 12px;
  transition: box-shadow 0.35s;
}

.board.is-active {
  box-shadow: 0 0 0 1px rgba(232, 195, 122, 0.09), 0 0 30px rgba(232, 195, 122, 0.04);
}

.board-row {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 6px;
  min-height: 0;
}

.big-row {
  flex: 1.32;
}

.small-row {
  flex: 0.7;
}

.midline {
  display: flex;
  align-items: center;
  gap: 10px;
  height: 30px;
  padding: 0 4px;
}

.midline-line {
  flex: 1;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(232, 195, 122, 0.36), transparent);
}

.midline-gem {
  width: 8px;
  height: 8px;
  transform: rotate(45deg);
  border: 1px solid rgba(232, 195, 122, 0.7);
  background: rgba(232, 195, 122, 0.18);
  box-shadow: 0 0 14px rgba(232, 195, 122, 0.35);
}

.ticker {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  height: 20px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 9px;
  color: rgba(160, 178, 214, 0.8);
}

.ticker-tag,
.ticker-mark {
  flex: none;
  padding: 1px 4px;
  border: 1px solid var(--line);
  border-radius: 2px;
  font-size: 6px;
  letter-spacing: 0.12em;
  color: var(--muted);
}

.ticker-mark {
  color: var(--gold);
  border-color: rgba(232, 195, 122, 0.3);
}

.ticker-tag.side-player {
  color: var(--gold);
}

.ticker-tag.side-enemy {
  color: var(--red);
}

/* ── slots & cards ──────────────────────────────────────── */

.slot {
  position: relative;
  display: flex;
  min-width: 0;
  min-height: 0;
  border: 1px dashed rgba(130, 160, 220, 0.17);
  border-radius: 8px;
  background:
    linear-gradient(180deg, rgba(22, 33, 60, 0.28), rgba(5, 9, 18, 0.42)),
    radial-gradient(ellipse at 50% 0%, rgba(90, 130, 255, 0.05), transparent 65%);
  box-shadow: inset 0 0 22px rgba(60, 100, 220, 0.025);
  transition: border-color 0.25s, background 0.25s, box-shadow 0.25s;
}

.slot.small {
  background:
    linear-gradient(180deg, rgba(20, 30, 52, 0.22), rgba(5, 9, 18, 0.36)),
    radial-gradient(ellipse at 50% 0%, rgba(111, 231, 255, 0.04), transparent 65%);
}

.slot.filled {
  border-color: transparent;
  background: transparent;
  box-shadow: none;
}

.slot-mark {
  margin: auto;
  font-family: var(--display);
  font-size: 8px;
  letter-spacing: 0.12em;
  color: rgba(140, 170, 230, 0.22);
  user-select: none;
}

.slot.can-place {
  border-color: rgba(232, 195, 122, 0.72);
  background: rgba(232, 195, 122, 0.075);
  box-shadow: inset 0 0 28px rgba(232, 195, 122, 0.1), 0 0 18px rgba(232, 195, 122, 0.06);
  cursor: pointer;
  animation: slotCall 1.7s ease-in-out infinite;
}

.slot.targetable {
  border-color: rgba(255, 95, 109, 0.85);
  box-shadow: 0 0 0 1px rgba(255, 95, 109, 0.5), 0 0 24px rgba(255, 95, 109, 0.3);
  cursor: crosshair;
  z-index: 4;
}

.slot.targetable .card {
  filter: drop-shadow(0 0 12px rgba(255, 95, 109, 0.5));
}

.slot.targetable .card:hover {
  transform: scale(1.03);
}

.battle-preview {
  position: absolute;
  left: 50%;
  bottom: 3px;
  z-index: 6;
  transform: translateX(-50%);
  padding: 2px 5px;
  border-radius: 3px;
  background: rgba(3, 6, 13, 0.9);
  border: 1px solid currentColor;
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 0.02em;
  white-space: nowrap;
  pointer-events: none;
  box-shadow: 0 3px 10px rgba(0, 0, 0, 0.5);
}

.battle-preview.win { color: #7dffc0; }
.battle-preview.lose { color: #ff7a85; }
.battle-preview.tie { color: var(--gold); }
.battle-preview.hold { color: var(--cyan); }

.card {
  position: relative;
  display: block;
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--ink);
  text-align: left;
  cursor: pointer;
  border-radius: 8px;
  transition: transform 0.18s ease, filter 0.2s ease, opacity 0.2s ease;
  touch-action: manipulation;
  user-select: none;
  -webkit-user-select: none;
}

.card-face {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border: 1px solid rgba(210, 230, 255, 0.2);
  border-radius: 8px;
  background: linear-gradient(160deg, var(--p3), #060a13 72%);
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.035),
    0 4px 14px rgba(0, 0, 0, 0.48);
  transition: border-color 0.2s, box-shadow 0.2s, filter 0.2s, opacity 0.2s;
}

.card-art {
  position: relative;
  flex: 1;
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  background:
    radial-gradient(ellipse 110% 90% at 50% 18%, var(--p2), var(--p3) 72%),
    var(--p3);
}

.card-art::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    repeating-linear-gradient(115deg, rgba(255, 255, 255, 0.05) 0 1px, transparent 1px 7px),
    radial-gradient(circle at 50% 120%, rgba(0, 0, 0, 0.55), transparent 60%);
  mix-blend-mode: overlay;
}

.card-art::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.1), transparent 30%, transparent 70%, rgba(0, 0, 0, 0.45));
  pointer-events: none;
}

.card-kanji {
  position: absolute;
  left: 50%;
  top: 51%;
  transform: translate(-50%, -50%) scale(2.35);
  font-size: 30px;
  font-weight: 900;
  line-height: 1;
  color: rgba(255, 255, 255, 0.09);
  letter-spacing: -0.08em;
  text-shadow: 0 2px 22px rgba(0, 0, 0, 0.5);
  pointer-events: none;
}

.card-glyph {
  position: relative;
  z-index: 1;
  font-size: clamp(19px, 2.35vw, 36px);
  line-height: 1;
  filter: drop-shadow(0 4px 9px rgba(0, 0, 0, 0.65));
}

.card-kind {
  position: absolute;
  top: 3px;
  left: 4px;
  z-index: 2;
  padding: 1px 3px;
  border-radius: 2px;
  background: rgba(2, 5, 11, 0.45);
  color: rgba(255, 255, 255, 0.62);
  font-size: 5.5px;
  letter-spacing: 0.13em;
}

.card-badges {
  position: absolute;
  top: 3px;
  right: 3px;
  z-index: 3;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
  pointer-events: none;
}

.mini-badge {
  padding: 1px 3px;
  border-radius: 2px;
  font-size: 5.5px;
  line-height: 1.2;
  letter-spacing: 0.04em;
  background: rgba(2, 5, 11, 0.72);
  border: 1px solid rgba(255, 255, 255, 0.16);
  white-space: nowrap;
}

.mini-badge.stop { color: #ff9dba; border-color: rgba(255, 95, 109, 0.5); }
.mini-badge.taunt { color: #ffd48a; border-color: rgba(255, 200, 100, 0.45); }
.mini-badge.shield { color: #9fe8ff; border-color: rgba(111, 231, 255, 0.45); }
.mini-badge.direct { color: #b8ffbf; border-color: rgba(143, 255, 200, 0.45); }
.mini-badge.buff { color: #d9c6ff; border-color: rgba(200, 182, 255, 0.45); }

.card-state {
  position: absolute;
  right: 3px;
  bottom: 3px;
  z-index: 3;
  display: flex;
  gap: 2px;
}

.card.monster .card-state {
  bottom: 19px;
}

.pip {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #28324b;
  box-shadow: inset 0 0 2px #000;
}

.pip.on {
  background: var(--cyan);
  box-shadow: 0 0 6px rgba(111, 231, 255, 0.9);
}

.pip.act.on {
  background: var(--gold);
  box-shadow: 0 0 6px rgba(232, 195, 122, 0.95);
}

.card-stats {
  position: absolute;
  left: 3px;
  right: 3px;
  bottom: 3px;
  z-index: 2;
  display: flex;
  justify-content: space-between;
  gap: 2px;
  pointer-events: none;
}

.stat {
  display: flex;
  align-items: baseline;
  gap: 2px;
  padding: 0 3px;
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 2px;
  background: rgba(2, 4, 10, 0.74);
  font-family: var(--display);
  font-size: clamp(8px, 0.9vw, 11px);
  font-weight: 700;
  line-height: 1.35;
  text-shadow: 0 1px 2px #000;
}

.stat i {
  font-style: normal;
  font-family: var(--font);
  font-size: 5px;
  letter-spacing: 0.05em;
  color: rgba(200, 215, 245, 0.55);
}

.stat.atk { color: #ffd6a0; }
.stat.def { color: #a8d8ff; }

.card-ready {
  position: absolute;
  right: 4px;
  bottom: 3px;
  z-index: 2;
  padding: 0 3px;
  border-radius: 2px;
  background: rgba(2, 4, 10, 0.7);
  border: 1px solid rgba(111, 231, 255, 0.24);
  color: rgba(111, 231, 255, 0.85);
  font-size: 5.5px;
  letter-spacing: 0.1em;
}

.card.act-used .card-ready {
  color: rgba(140, 156, 190, 0.6);
  border-color: rgba(150, 170, 210, 0.15);
}

.card-name {
  flex: none;
  padding: 3px 4px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  background: linear-gradient(180deg, rgba(4, 8, 16, 0.35), rgba(3, 6, 12, 0.94));
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  font-size: clamp(7px, 0.82vw, 10px);
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: 0.015em;
}

.card.in-hand {
  width: var(--hand-w);
  height: var(--hand-h);
  flex: 0 0 auto;
}

.card.in-hand .card-art {
  flex: 0 0 64px;
}

.card.in-hand .card-glyph {
  font-size: 26px;
}

.card.in-hand .card-kanji {
  font-size: 24px;
}

.card-actline {
  display: block;
  flex: none;
  height: 43px;
  padding: 3px 4px 4px;
  overflow: hidden;
  background: rgba(3, 6, 13, 0.92);
  border-top: 1px solid rgba(150, 180, 255, 0.1);
  color: #adbce0;
  font-size: 7px;
  line-height: 1.32;
}

.card-actline b {
  display: block;
  margin-bottom: 1px;
  color: var(--gold);
  font-size: 7.5px;
  font-weight: 700;
  letter-spacing: 0.03em;
}

.card.playable .card-face {
  border-color: rgba(232, 195, 122, 0.38);
  box-shadow: inset 0 0 0 1px rgba(232, 195, 122, 0.08), 0 4px 16px rgba(0, 0, 0, 0.5);
}

.card.selected {
  z-index: 6;
  transform: translateY(-4px);
}

.card.selected .card-face {
  border-color: var(--gold);
  box-shadow:
    0 0 0 1px rgba(232, 195, 122, 0.8),
    0 0 28px rgba(232, 195, 122, 0.45),
    0 8px 24px rgba(0, 0, 0, 0.55);
}

.card.act-used .card-face {
  filter: saturate(0.55) brightness(0.8);
}

.card.act-used .card-art::after {
  background: repeating-linear-gradient(135deg, rgba(0, 0, 0, 0.22) 0 5px, transparent 5px 10px);
}

.card.spent {
  filter: grayscale(0.8) brightness(0.62);
  opacity: 0.7;
}

.spent-veil {
  position: absolute;
  inset: 0;
  z-index: 4;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: rgba(3, 6, 12, 0.24);
  color: rgba(230, 238, 255, 0.55);
  font-family: var(--display);
  font-size: 7px;
  letter-spacing: 0.18em;
  pointer-events: none;
}

.card.enter {
  animation: cardEnter 0.5s cubic-bezier(0.18, 0.8, 0.28, 1) both;
}

.card.destroying {
  z-index: 8;
  pointer-events: none;
}

.card.destroying .card-face {
  animation: cardDestroy 0.42s ease-in forwards;
}

@keyframes cardEnter {
  from {
    opacity: 0;
    transform: translateY(16px) scale(0.86) rotateY(14deg);
    filter: brightness(2);
  }
  to {
    opacity: 1;
    transform: none;
    filter: brightness(1);
  }
}

@keyframes cardDestroy {
  0% { opacity: 1; filter: brightness(1); }
  35% { opacity: 1; filter: brightness(2.2) saturate(0.4); }
  100% {
    opacity: 0;
    transform: scale(0.62) rotate(7deg);
    filter: brightness(0.4) saturate(0);
  }
}

@keyframes slotCall {
  0%, 100% { box-shadow: inset 0 0 28px rgba(232, 195, 122, 0.08), 0 0 14px rgba(232, 195, 122, 0.04); }
  50% { box-shadow: inset 0 0 34px rgba(232, 195, 122, 0.16), 0 0 24px rgba(232, 195, 122, 0.1); }
}

@media (hover: hover) {
  .card:hover {
    transform: translateY(-3px);
    z-index: 7;
  }

  .card:hover .card-face {
    border-color: rgba(225, 238, 255, 0.48);
    box-shadow: 0 8px 22px rgba(0, 0, 0, 0.55);
  }

  .card.selected:hover {
    transform: translateY(-4px);
  }
}

/* ── player strips ──────────────────────────────────────── */

.player-strip {
  position: relative;
  display: flex;
  align-items: center;
  gap: 9px;
  flex: none;
  min-height: 45px;
  padding: 5px 9px 5px 8px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 9px;
  background:
    linear-gradient(90deg, rgba(16, 26, 50, 0.88), rgba(7, 12, 24, 0.58)),
    radial-gradient(ellipse at 0% 50%, rgba(232, 195, 122, 0.06), transparent 60%);
  transition: border-color 0.3s, box-shadow 0.3s;
}

.player-strip::before {
  content: '';
  position: absolute;
  left: 0;
  top: 12%;
  bottom: 12%;
  width: 2px;
  border-radius: 2px;
  background: linear-gradient(180deg, transparent, var(--gold), transparent);
  opacity: 0.8;
}

.enemy-strip {
  background:
    linear-gradient(90deg, rgba(34, 17, 30, 0.78), rgba(7, 12, 24, 0.58)),
    radial-gradient(ellipse at 0% 50%, rgba(255, 95, 109, 0.07), transparent 60%);
}

.enemy-strip::before {
  background: linear-gradient(180deg, transparent, var(--red), transparent);
}

.player-strip.is-active {
  border-color: rgba(232, 195, 122, 0.32);
  box-shadow: 0 0 24px rgba(232, 195, 122, 0.06);
}

.enemy-strip.is-active {
  border-color: rgba(255, 95, 109, 0.26);
  box-shadow: 0 0 24px rgba(255, 95, 109, 0.05);
}

.avatar {
  flex: none;
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(232, 195, 122, 0.42);
  border-radius: 50%;
  background:
    radial-gradient(circle at 35% 25%, rgba(255, 235, 180, 0.26), transparent 55%),
    linear-gradient(160deg, rgba(52, 42, 24, 0.9), rgba(8, 12, 22, 0.9));
  box-shadow: 0 0 16px rgba(232, 195, 122, 0.14);
}

.avatar span {
  font-family: var(--display);
  font-size: 13px;
  font-weight: 700;
  color: var(--gold-2);
  text-shadow: 0 0 10px rgba(232, 195, 122, 0.5);
}

.avatar-enemy {
  border-color: rgba(255, 95, 109, 0.42);
  background:
    radial-gradient(circle at 35% 25%, rgba(255, 160, 180, 0.2), transparent 55%),
    linear-gradient(160deg, rgba(50, 18, 32, 0.9), rgba(8, 12, 22, 0.9));
  box-shadow: 0 0 16px rgba(255, 95, 109, 0.13);
}

.avatar-enemy span {
  color: #ffc0c8;
  text-shadow: 0 0 10px rgba(255, 95, 109, 0.5);
}

.p-info {
  flex: 1;
  min-width: 0;
}

.p-name-row {
  display: flex;
  align-items: center;
  gap: 5px;
  min-width: 0;
  line-height: 1.2;
}

.p-name {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.07em;
}

.active-badge {
  flex: none;
  padding: 1px 4px;
  border: 1px solid rgba(232, 195, 122, 0.36);
  border-radius: 2px;
  color: var(--gold);
  font-size: 5.5px;
  letter-spacing: 0.16em;
}

.enemy-strip .active-badge {
  border-color: rgba(255, 95, 109, 0.34);
  color: #ff9aa5;
}

.status-badge {
  flex: none;
  padding: 1px 4px;
  border: 1px solid rgba(200, 182, 255, 0.32);
  border-radius: 2px;
  color: #d7c8ff;
  font-size: 5.5px;
  letter-spacing: 0.08em;
  background: rgba(80, 60, 140, 0.18);
}

.status-badge.time {
  border-color: rgba(111, 231, 255, 0.3);
  color: #a8f0ff;
  background: rgba(40, 110, 140, 0.16);
}

.thinking-dots {
  display: inline-flex;
  gap: 2px;
  align-items: center;
  margin-left: 2px;
}

.thinking-dots i {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: var(--red);
  animation: think 1s infinite;
}

.thinking-dots i:nth-child(2) { animation-delay: 0.15s; }
.thinking-dots i:nth-child(3) { animation-delay: 0.3s; }

@keyframes think {
  0%, 60%, 100% { opacity: 0.25; transform: translateY(0); }
  30% { opacity: 1; transform: translateY(-2px); }
}

.lp-row {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-top: 2px;
}

.lp-num {
  min-width: 42px;
  text-align: right;
  font-family: var(--display);
  font-size: 14px;
  font-weight: 700;
  line-height: 1;
  color: var(--gold-2);
  text-shadow: 0 0 12px rgba(232, 195, 122, 0.25);
  font-variant-numeric: tabular-nums;
}

.enemy-strip .lp-num {
  color: #ffc3c9;
  text-shadow: 0 0 12px rgba(255, 95, 109, 0.22);
}

.lp-num.low {
  color: #ff7a85 !important;
  animation: pulseLow 1s infinite;
}

@keyframes pulseLow {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.55; }
}

.lp-max {
  flex: none;
  font-size: 6.5px;
  color: rgba(160, 178, 214, 0.55);
}

.lp-bar {
  position: relative;
  flex: 1;
  height: 5px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.06);
}

.lp-bar i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #b98a42, var(--gold), #ffc76b);
  box-shadow: 0 0 10px rgba(232, 195, 122, 0.55);
  transition: width 0.55s cubic-bezier(0.2, 0.8, 0.3, 1);
}

.enemy-strip .lp-bar i {
  background: linear-gradient(90deg, #a83248, var(--red), #ff9a7a);
  box-shadow: 0 0 10px rgba(255, 95, 109, 0.5);
}

.lp-tag {
  flex: none;
  font-size: 5.5px;
  letter-spacing: 0.14em;
  color: rgba(160, 178, 214, 0.5);
}

.p-piles {
  display: flex;
  align-items: center;
  gap: 7px;
  flex: none;
}

.pile {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-width: 22px;
  line-height: 1;
}

.pile b {
  font-family: var(--display);
  font-size: 10px;
  color: #dce7ff;
  font-variant-numeric: tabular-nums;
}

.pile small {
  margin-top: 2px;
  font-size: 4.5px;
  letter-spacing: 0.12em;
  color: rgba(150, 170, 205, 0.6);
}

.pile.grave b {
  color: #bda9df;
}

.enemy-hand {
  display: flex;
  align-items: center;
  margin-right: 1px;
}

.mini-back {
  width: 9px;
  height: 13px;
  margin-left: -4px;
  border: 1px solid rgba(160, 195, 255, 0.32);
  border-radius: 2px;
  background:
    repeating-linear-gradient(135deg, rgba(255, 255, 255, 0.08) 0 1px, transparent 1px 3px),
    linear-gradient(150deg, #233458, #0a1224);
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.45);
}

.mini-back:first-child {
  margin-left: 0;
}

.hand-extra {
  margin-left: 2px;
  font-size: 6px;
  color: var(--muted);
}

@keyframes blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.3; }
}

