input.newString:
/* ── duel log ───────────────────────────────────────────── */

.log-panel {
  display: flex;
  flex-direction: column;
  min-height: 0;
  margin: 4px 0 8px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 10px;
  background:
    linear-gradient(180deg, rgba(12, 20, 40, 0.78), rgba(5, 9, 18, 0.82)),
    radial-gradient(ellipse at 50% 0%, rgba(80, 120, 255, 0.06), transparent 65%);
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.24);
  backdrop-filter: blur(8px);
}

.log-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex: none;
  padding: 9px 11px 8px;
  border-bottom: 1px solid var(--line);
  font-size: 7px;
  letter-spacing: 0.22em;
  color: var(--gold);
}

.log-live {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: rgba(143, 255, 200, 0.7);
  font-size: 5.5px;
}

.log-live i {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 6px var(--green);
  animation: blink 1.4s infinite;
}

.log-list {
  flex: 1;
  min-height: 0;
  margin: 0;
  padding: 7px 9px;
  overflow-y: auto;
  list-style: none;
  scrollbar-width: thin;
  scrollbar-color: rgba(120, 150, 210, 0.3) transparent;
}

.log-entry {
  display: flex;
  gap: 6px;
  padding: 3px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.028);
  font-size: 8.5px;
  line-height: 1.45;
}

.log-tag {
  flex: none;
  width: 20px;
  padding-top: 1px;
  font-size: 5.5px;
  letter-spacing: 0.08em;
  color: rgba(150, 170, 205, 0.6);
}

.side-player .log-tag { color: var(--gold); }
.side-enemy .log-tag { color: var(--red); }

.log-text {
  color: #b8c5e2;
  word-break: break-word;
}

.kind-damage .log-text { color: #ffaab3; }
.kind-cost .log-text { color: #ffcf8a; }
.kind-heal .log-text { color: #9bf5c8; }
.kind-act .log-text { color: #d3c3ff; }
.kind-battle .log-text { color: #ffd7a1; }
.kind-turn .log-text { color: var(--gold-2); font-weight: 700; }
.kind-summon .log-text { color: #a8d7ff; }
.kind-set .log-text { color: #9fe8ff; }
.kind-ward .log-text { color: var(--violet); }
.kind-stun .log-text { color: #ff9dba; }
.kind-system .log-text { color: rgba(160, 178, 214, 0.7); }

.log-legend {
  display: flex;
  gap: 13px;
  flex: none;
  padding: 7px 11px;
  border-top: 1px solid var(--line);
  font-size: 5.5px;
  letter-spacing: 0.1em;
  color: rgba(150, 170, 205, 0.6);
}

.log-legend span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.dot-you,
.dot-foe {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--gold);
}

.dot-foe { background: var(--red); }

/* ── hand & command ─────────────────────────────────────── */

.hand-area {
  position: relative;
  z-index: 7;
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 5px 18px max(8px, env(safe-area-inset-bottom));
  background: linear-gradient(180deg, transparent, rgba(3, 6, 12, 0.8) 26%, rgba(3, 6, 12, 0.94));
}

.action-bar {
  position: relative;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 5px 12px;
  min-height: 62px;
  padding: 7px 11px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background:
    linear-gradient(90deg, rgba(14, 23, 44, 0.92), rgba(7, 12, 24, 0.8)),
    radial-gradient(ellipse at 0% 50%, rgba(232, 195, 122, 0.04), transparent 55%);
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.32);
  backdrop-filter: blur(10px);
}

.ab-info {
  flex: 1 1 320px;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.ab-kicker {
  font-size: 5.5px;
  letter-spacing: 0.18em;
  color: var(--gold);
  text-transform: uppercase;
}

.ab-kicker.target {
  color: #ff8792;
  animation: blink 1.2s infinite;
}

.ab-kicker.foe {
  color: #ff8792;
}

.ab-name {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: 0.03em;
}

.ab-meta {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 7.5px;
  color: var(--muted);
}

.ab-act {
  margin: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 8px;
  color: #aebcda;
}

.ab-act b {
  color: var(--gold);
  font-weight: 700;
}

.ab-actions {
  flex: 0 0 auto;
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 5px;
}

.ab-note {
  flex: 1 0 100%;
  margin-top: -2px;
  font-size: 7px;
  line-height: 1.3;
  color: rgba(160, 178, 214, 0.72);
}

.ab-note.warn {
  color: #ffad9a;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  min-height: 30px;
  padding: 6px 12px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: rgba(20, 31, 57, 0.72);
  color: #dbe6ff;
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.02em;
  white-space: nowrap;
  cursor: pointer;
  transition: border-color 0.18s, background 0.18s, transform 0.18s, color 0.18s;
}

.btn:hover {
  border-color: rgba(200, 220, 255, 0.4);
  background: rgba(30, 45, 78, 0.82);
  transform: translateY(-1px);
}

.btn.primary {
  border-color: rgba(232, 195, 122, 0.55);
  background: linear-gradient(180deg, rgba(232, 195, 122, 0.22), rgba(146, 100, 38, 0.16));
  color: #ffe9b8;
  box-shadow: 0 0 18px rgba(232, 195, 122, 0.12);
}

.btn.primary:hover {
  border-color: rgba(232, 195, 122, 0.85);
  background: linear-gradient(180deg, rgba(232, 195, 122, 0.32), rgba(146, 100, 38, 0.2));
}

.btn.ghost {
  background: rgba(10, 17, 32, 0.56);
  color: #b8c6e4;
}

.btn[aria-disabled='true'] {
  opacity: 0.42;
  filter: grayscale(0.55);
  cursor: not-allowed;
  transform: none;
}

.btn b {
  font-family: var(--display);
  font-size: 11px;
  color: var(--gold-2);
}

.direct-btn {
  border-color: rgba(255, 95, 109, 0.5) !important;
  background: linear-gradient(180deg, rgba(255, 95, 109, 0.2), rgba(100, 20, 35, 0.18)) !important;
  color: #ffd0d5 !important;
}

.hand-row {
  display: flex;
  align-items: flex-end;
  gap: 10px;
  min-height: 0;
}

.hand-scroll {
  flex: 1;
  min-width: 0;
  overflow-x: auto;
  overflow-y: hidden;
  padding: 5px 3px 3px;
  scrollbar-width: thin;
  scrollbar-color: rgba(120, 150, 210, 0.28) transparent;
  touch-action: pan-x;
}

.hand {
  display: flex;
  align-items: flex-end;
  gap: 7px;
  width: max-content;
  min-height: var(--hand-h);
  padding: 0 3px;
}

.hand-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 200px;
  height: var(--hand-h);
  border: 1px dashed var(--line);
  border-radius: 8px;
  color: rgba(150, 170, 205, 0.45);
  font-size: 8px;
  letter-spacing: 0.1em;
}

.end-turn-btn {
  flex: none;
  width: 96px;
  height: 74px;
  margin-bottom: 38px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  padding: 0;
  border: 1px solid rgba(232, 195, 122, 0.48);
  border-radius: 9px;
  background:
    radial-gradient(ellipse at 50% 0%, rgba(232, 195, 122, 0.17), transparent 70%),
    linear-gradient(180deg, rgba(28, 36, 58, 0.92), rgba(10, 16, 30, 0.92));
  color: var(--gold-2);
  cursor: pointer;
  box-shadow: 0 0 22px rgba(232, 195, 122, 0.08), 0 8px 20px rgba(0, 0, 0, 0.35);
  transition: border-color 0.2s, box-shadow 0.2s, transform 0.2s, opacity 0.2s;
}

.end-turn-btn:hover:not(:disabled) {
  border-color: rgba(232, 195, 122, 0.9);
  box-shadow: 0 0 30px rgba(232, 195, 122, 0.2), 0 8px 20px rgba(0, 0, 0, 0.35);
  transform: translateY(-2px);
}

.end-turn-btn:disabled {
  opacity: 0.32;
  filter: grayscale(0.6);
  cursor: not-allowed;
}

.end-turn-main {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.end-turn-sub {
  font-size: 5.5px;
  letter-spacing: 0.18em;
  color: rgba(232, 195, 122, 0.66);
}

