input.newString:
/* ── intro ──────────────────────────────────────────────── */

.overlay {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 22px;
  background:
    radial-gradient(ellipse 70% 60% at 50% 35%, rgba(24, 40, 82, 0.55), transparent 75%),
    rgba(2, 4, 9, 0.86);
  backdrop-filter: blur(9px);
  animation: overlayIn 0.35s ease-out;
}

.overlay.hidden {
  display: none;
}

.intro-overlay {
  background:
    radial-gradient(ellipse 60% 55% at 50% 40%, rgba(38, 60, 112, 0.45), transparent 72%),
    radial-gradient(ellipse 45% 40% at 75% 70%, rgba(90, 40, 110, 0.22), transparent 70%),
    rgba(2, 4, 9, 0.84);
}

.intro-overlay.leaving {
  animation: overlayOut 0.45s ease-in forwards;
}

.intro-inner {
  position: relative;
  z-index: 1;
  width: min(620px, 100%);
  text-align: center;
  animation: introRise 0.75s cubic-bezier(0.18, 0.9, 0.26, 1) both;
}

.intro-sigil {
  position: relative;
  width: 104px;
  height: 104px;
  margin: 0 auto 16px;
}

.sigil-ring {
  position: absolute;
  inset: 0;
  border: 1px solid rgba(232, 195, 122, 0.36);
  border-radius: 50%;
  animation: rotateRing 28s linear infinite;
}

.sigil-ring::before,
.sigil-ring::after {
  content: '';
  position: absolute;
  left: 50%;
  top: -3px;
  width: 5px;
  height: 5px;
  transform: translateX(-50%) rotate(45deg);
  background: var(--gold);
  box-shadow: 0 0 10px var(--gold);
}

.sigil-ring::after {
  top: auto;
  bottom: -3px;
  background: var(--cyan);
  box-shadow: 0 0 10px var(--cyan);
}

.sigil-ring-2 {
  inset: 13%;
  border-style: dashed;
  border-color: rgba(111, 231, 255, 0.26);
  animation-direction: reverse;
  animation-duration: 19s;
}

.sigil-core {
  position: absolute;
  inset: 29%;
  display: grid;
  place-items: center;
  border: 1px solid rgba(232, 195, 122, 0.48);
  border-radius: 50%;
  background: radial-gradient(circle, rgba(232, 195, 122, 0.18), rgba(5, 9, 18, 0.8) 70%);
  box-shadow: 0 0 34px rgba(232, 195, 122, 0.15), inset 0 0 16px rgba(232, 195, 122, 0.12);
  font-family: var(--display);
  font-size: 21px;
  font-weight: 700;
  letter-spacing: 0.05em;
  color: var(--gold-2);
  text-shadow: 0 0 12px rgba(232, 195, 122, 0.55);
}

.intro-kicker {
  margin: 0 0 7px;
  font-size: 7px;
  letter-spacing: 0.32em;
  color: rgba(111, 231, 255, 0.68);
}

.intro-title {
  margin: 0;
  font-family: var(--display);
  font-size: clamp(52px, 8.5vw, 98px);
  font-weight: 700;
  line-height: 0.92;
  letter-spacing: 0.1em;
  background: linear-gradient(180deg, #fff9e8 0%, #e8c37a 52%, #9f6a25 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 6px 30px rgba(232, 195, 122, 0.2));
}

.intro-title span {
  background: linear-gradient(180deg, #e9fdff 0%, #6fe7ff 48%, #1a718c 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.intro-sub {
  margin: 8px 0 0;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.38em;
  color: #e7edfb;
  text-shadow: 0 0 22px rgba(150, 190, 255, 0.18);
}

.intro-lead {
  margin: 16px 0 0;
  font-size: 10.5px;
  line-height: 1.9;
  letter-spacing: 0.08em;
  color: #a9b8d8;
}

.intro-chips {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 6px;
  margin: 18px 0 22px;
}

.intro-chips span {
  padding: 4px 9px;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: rgba(10, 17, 32, 0.55);
  font-size: 7.5px;
  letter-spacing: 0.08em;
  color: #9fafd0;
}

.intro-chips b {
  margin-right: 3px;
  color: var(--gold-2);
  font-family: var(--display);
  font-size: 10px;
}

.intro-actions {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 11px;
}

.start-btn {
  position: relative;
  min-width: 250px;
  padding: 12px 30px 11px;
  overflow: hidden;
  border: 1px solid rgba(232, 195, 122, 0.62);
  border-radius: 7px;
  background:
    linear-gradient(180deg, rgba(232, 195, 122, 0.24), rgba(108, 70, 22, 0.18)),
    rgba(14, 20, 34, 0.8);
  color: #fff1cb;
  cursor: pointer;
  box-shadow: 0 0 36px rgba(232, 195, 122, 0.13), 0 10px 30px rgba(0, 0, 0, 0.38);
  transition: border-color 0.2s, box-shadow 0.2s, transform 0.2s;
}

.start-btn::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(110deg, transparent 25%, rgba(255, 245, 210, 0.28) 48%, transparent 70%);
  transform: translateX(-140%);
  animation: sheen 3.4s ease-in-out infinite;
}

.start-btn span {
  position: relative;
  display: block;
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.22em;
}

.start-btn small {
  position: relative;
  display: block;
  margin-top: 3px;
  font-size: 5.5px;
  letter-spacing: 0.34em;
  color: rgba(255, 241, 203, 0.6);
}

.start-btn:hover {
  border-color: var(--gold);
  box-shadow: 0 0 48px rgba(232, 195, 122, 0.26), 0 10px 30px rgba(0, 0, 0, 0.38);
  transform: translateY(-2px);
}

.text-btn {
  padding: 2px 1px;
  border: 0;
  border-bottom: 1px solid rgba(232, 195, 122, 0.3);
  background: none;
  color: rgba(170, 186, 216, 0.8);
  font-size: 7.5px;
  letter-spacing: 0.14em;
  cursor: pointer;
  transition: color 0.2s, border-color 0.2s;
}

.text-btn:hover {
  color: var(--gold-2);
  border-color: var(--gold);
}

.intro-foot {
  margin: 20px 0 0;
  font-size: 6.5px;
  letter-spacing: 0.12em;
  color: rgba(140, 156, 194, 0.5);
}

@keyframes introRise {
  from { opacity: 0; transform: translateY(18px) scale(0.98); }
  to { opacity: 1; transform: none; }
}

@keyframes rotateRing {
  to { transform: rotate(360deg); }
}

@keyframes sheen {
  0%, 35% { transform: translateX(-140%); }
  65%, 100% { transform: translateX(140%); }
}

@keyframes overlayIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes overlayOut {
  to { opacity: 0; transform: scale(1.02); }
}

/* ── rules modal ───────────────────────────────────────── */

.modal-overlay {
  z-index: 70;
  background: rgba(2, 4, 9, 0.76);
}

.modal {
  display: flex;
  flex-direction: column;
  width: min(760px, 100%);
  max-height: min(86dvh, 780px);
  overflow: hidden;
  border: 1px solid rgba(232, 195, 122, 0.32);
  border-radius: 13px;
  background:
    radial-gradient(ellipse at 50% 0%, rgba(60, 90, 160, 0.16), transparent 55%),
    linear-gradient(165deg, #0d1730, #05090f 78%);
  box-shadow: 0 30px 100px rgba(0, 0, 0, 0.65), 0 0 60px rgba(80, 120, 220, 0.08);
  animation: modalIn 0.36s cubic-bezier(0.18, 0.9, 0.26, 1);
}

@keyframes modalIn {
  from { opacity: 0; transform: translateY(16px) scale(0.97); }
  to { opacity: 1; transform: none; }
}

.modal-head {
  position: relative;
  flex: none;
  padding: 16px 20px 12px;
  border-bottom: 1px solid var(--line);
}

.modal-kicker {
  font-size: 6px;
  letter-spacing: 0.28em;
  color: var(--cyan);
}

.modal-head h2 {
  margin: 4px 0 0;
  font-size: 19px;
  font-weight: 700;
  letter-spacing: 0.1em;
}

.modal-close {
  position: absolute;
  top: 13px;
  right: 14px;
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: rgba(10, 17, 32, 0.7);
  color: #b8c6e4;
  font-size: 16px;
  line-height: 1;
  cursor: pointer;
}

.modal-close:hover {
  border-color: rgba(255, 95, 109, 0.5);
  color: #ffaab3;
}

.rules-body {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 15px 24px;
  padding: 16px 22px;
  overflow-y: auto;
  scrollbar-width: thin;
}

.rules-body section {
  min-width: 0;
}

.rules-body h3 {
  margin: 0 0 4px;
  color: var(--gold);
  font-size: 10px;
  letter-spacing: 0.08em;
}

.rules-body p {
  margin: 0;
  color: #aebcda;
  font-size: 9.5px;
  line-height: 1.75;
}

.rules-body strong {
  color: #f0dfb4;
  font-weight: 700;
}

.rules-tip {
  grid-column: 1 / -1;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}

.rules-tip kbd {
  display: inline-block;
  margin: 0 2px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.05);
  font-size: 8px;
  color: #dbe6ff;
}

.modal-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex: none;
  padding: 10px 20px max(12px, env(safe-area-inset-bottom));
  border-top: 1px solid var(--line);
  color: rgba(150, 170, 205, 0.5);
  font-size: 6px;
  letter-spacing: 0.14em;
}

/* ── game over ──────────────────────────────────────────── */

.gameover-overlay {
  z-index: 60;
  background:
    radial-gradient(ellipse 60% 55% at 50% 45%, rgba(70, 55, 20, 0.24), transparent 70%),
    rgba(2, 4, 9, 0.88);
}

.gameover-card {
  position: relative;
  width: min(540px, 100%);
  padding: 30px 24px 26px;
  text-align: center;
  border: 1px solid rgba(232, 195, 122, 0.3);
  border-radius: 14px;
  background:
    radial-gradient(ellipse at 50% 0%, rgba(232, 195, 122, 0.1), transparent 60%),
    linear-gradient(165deg, rgba(18, 27, 48, 0.96), rgba(5, 9, 16, 0.98));
  box-shadow: 0 30px 100px rgba(0, 0, 0, 0.65);
  animation: modalIn 0.55s cubic-bezier(0.18, 0.9, 0.26, 1);
}

.gameover-card.lose {
  border-color: rgba(255, 95, 109, 0.26);
  background:
    radial-gradient(ellipse at 50% 0%, rgba(160, 30, 55, 0.16), transparent 60%),
    linear-gradient(165deg, rgba(28, 17, 28, 0.96), rgba(5, 9, 16, 0.98));
}

.gameover-kicker {
  margin: 0;
  font-size: 6.5px;
  letter-spacing: 0.24em;
  color: var(--cyan);
}

.gameover-card.lose .gameover-kicker {
  color: #ff9aa5;
}

.gameover-title {
  margin: 8px 0 2px;
  font-family: var(--display);
  font-size: clamp(48px, 9vw, 88px);
  font-weight: 700;
  line-height: 1;
  letter-spacing: 0.08em;
  background: linear-gradient(180deg, #fff9e4, #e8c37a 55%, #9f6a25);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 6px 28px rgba(232, 195, 122, 0.25));
}

.gameover-card.lose .gameover-title {
  background: linear-gradient(180deg, #ffe1e4, #ff5f6d 55%, #7d1e2d);
  -webkit-background-clip: text;
  background-clip: text;
  filter: drop-shadow(0 6px 28px rgba(255, 95, 109, 0.2));
}

.gameover-sub {
  margin: 4px 0 0;
  font-size: 10px;
  letter-spacing: 0.16em;
  color: #b9c6e4;
}

.gameover-stats {
  display: flex;
  justify-content: center;
  gap: 22px;
  margin: 24px 0 26px;
  padding: 12px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.gameover-stats div {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.gameover-stats span {
  font-size: 5.5px;
  letter-spacing: 0.16em;
  color: rgba(150, 170, 205, 0.65);
}

.gameover-stats b {
  font-family: var(--display);
  font-size: 18px;
  color: var(--gold-2);
  font-variant-numeric: tabular-nums;
}

.gameover-card.lose .gameover-stats b {
  color: #ffc4ca;
}

.gameover-actions {
  display: flex;
  justify-content: center;
  gap: 8px;
}

/* ── toast / banner / fx ────────────────────────────────── */

.toast-stack {
  position: fixed;
  left: 50%;
  bottom: max(238px, calc(env(safe-area-inset-bottom) + 238px));
  z-index: 80;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  transform: translateX(-50%);
  pointer-events: none;
}

.toast {
  padding: 7px 13px;
  border: 1px solid rgba(255, 170, 140, 0.35);
  border-radius: 5px;
  background: rgba(16, 12, 20, 0.92);
  color: #ffd4c8;
  font-size: 9px;
  letter-spacing: 0.04em;
  box-shadow: 0 8px 26px rgba(0, 0, 0, 0.5);
  animation: toastIn 0.28s cubic-bezier(0.18, 0.9, 0.26, 1);
}

.toast.out {
  animation: toastOut 0.3s ease-in forwards;
}

@keyframes toastIn {
  from { opacity: 0; transform: translateY(8px) scale(0.96); }
  to { opacity: 1; transform: none; }
}

@keyframes toastOut {
  to { opacity: 0; transform: translateY(-6px) scale(0.97); }
}

.turn-banner {
  position: fixed;
  left: 50%;
  top: 43%;
  z-index: 40;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  transform: translate(-50%, -50%) scale(0.92);
  opacity: 0;
  pointer-events: none;
  text-align: center;
}

.turn-banner.show {
  animation: bannerShow 1.5s cubic-bezier(0.2, 0.8, 0.3, 1) forwards;
}

.turn-banner span {
  font-family: var(--display);
  font-size: clamp(26px, 5vw, 52px);
  font-weight: 700;
  letter-spacing: 0.18em;
  color: #fbf1d6;
  text-shadow: 0 0 34px rgba(232, 195, 122, 0.38), 0 6px 30px rgba(0, 0, 0, 0.6);
}

.turn-banner small {
  font-size: 7px;
  letter-spacing: 0.5em;
  color: var(--gold);
}

@keyframes bannerShow {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(0.9); filter: blur(4px); }
  18% { opacity: 1; transform: translate(-50%, -50%) scale(1); filter: blur(0); }
  72% { opacity: 1; transform: translate(-50%, -50%) scale(1); filter: blur(0); }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(1.04); filter: blur(2px); }
}

.fx-layer {
  position: fixed;
  inset: 0;
  z-index: 45;
  overflow: hidden;
  pointer-events: none;
}

.fx-float {
  position: fixed;
  z-index: 3;
  font-family: var(--display);
  font-size: clamp(18px, 2.3vw, 30px);
  font-weight: 700;
  letter-spacing: 0.02em;
  white-space: nowrap;
  text-shadow: 0 2px 8px #000, 0 0 18px currentColor;
  will-change: transform, opacity;
}

.fx-float.damage { color: #ff7a85; }
.fx-float.heal { color: #8fffc8; }
.fx-float.cost { color: #ffcf7a; }
.fx-float.negate { color: #c8b6ff; font-size: clamp(14px, 1.6vw, 22px); letter-spacing: 0.14em; }

.fx-slash {
  position: fixed;
  z-index: 2;
  width: 110px;
  height: 7px;
  border-radius: 99px;
  background: linear-gradient(90deg, transparent, var(--slash), #fff, var(--slash), transparent);
  box-shadow: 0 0 24px var(--slash), 0 0 60px var(--slash);
  will-change: transform, opacity;
}

.fx-ring {
  position: fixed;
  z-index: 1;
  width: 80px;
  height: 80px;
  border: 2px solid var(--ring);
  border-radius: 50%;
  box-shadow: 0 0 24px var(--ring), inset 0 0 18px var(--ring);
  will-change: transform, opacity;
}

.fx-spark {
  position: fixed;
  z-index: 2;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--gold);
  box-shadow: 0 0 9px var(--gold);
  will-change: transform, opacity;
}

.confetti {
  position: fixed;
  z-index: 1;
  border-radius: 1px;
  will-change: transform, opacity;
}

#app.shake-1 { animation: shake1 0.38s ease-in-out; }
#app.shake-2 { animation: shake2 0.46s ease-in-out; }

@keyframes shake1 {
  0%, 100% { transform: translate(0, 0); }
  25% { transform: translate(-2px, 1px); }
  50% { transform: translate(2px, -1px); }
  75% { transform: translate(-1px, -1px); }
}

@keyframes shake2 {
  0%, 100% { transform: translate(0, 0); }
  15% { transform: translate(-5px, 2px) rotate(-0.15deg); }
  35% { transform: translate(5px, -2px) rotate(0.15deg); }
  55% { transform: translate(-4px, -1px); }
  75% { transform: translate(3px, 2px); }
}

.noscript {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  place-items: center;
  background: #050811;
  color: #e9eefc;
  font-size: 14px;
}

