async () => {
  const z = window.__z12;
  const s = z.state;
  const P = 'player', E = 'enemy';
  const out = [];
  const reset = () => {
    s.started = true; s.over = false; s.busy = false; s.active = P; s.turnSerial = 10;
    s.selectedUid = null; s.attackerUid = null; s.removals.length = 0; s.fx.length = 0; s.log.length = 0;
    for (const side of [P, E]) {
      const p = s.players[side];
      p.lp = 3000; p.maxLp = 3000; p.deck = []; p.hand = []; p.grave = [];
      p.big = Array(6).fill(null); p.small = Array(6).fill(null);
      p.summonUsed = 0; p.setUsed = 0; p.extraSummons = 0; p.ward = 0; p.skipDraw = false;
    }
  };
  const add = (id, side, zone = 'big', index = 0, serial = -99) => {
    const c = z.makeCard(id, side); c.zone = zone; c.index = index; c.summonedSerial = serial;
    s.players[side][zone][index] = c; return c;
  };
  const run = async (name, fn) => {
    reset();
    try { await fn(); out.push({ name, ok: true }); }
    catch (err) { out.push({ name, ok: false, error: String(err && err.stack || err) }); }
  };
  const assert = (v, msg) => { if (!v) throw new Error(msg); };

  await run('direct attack', async () => {
    const a = add('flarewolf', P);
    await z.G ? null : null;
    const { performAttack } = window.__z12;
    assert(typeof performAttack === 'function', 'performAttack not exposed');
    await performAttack(a, null);
    assert(s.players[E].lp === 1600, 'direct damage wrong: ' + s.players[E].lp);
    assert(a.attacked === true, 'attacker not marked');
    assert(!s.over, 'unexpected over');
  });

  await run('winning battle', async () => {
    const a = add('varga', P); const d = add('golem', E);
    await z.performAttack(a, d.uid);
    assert(s.players[E].lp === 1600, 'battle damage wrong: ' + s.players[E].lp);
    assert(!s.players[E].big[0], 'defender still on field');
    assert(s.players[E].grave.length === 1, 'defender not in grave');
    assert(s.players[P].big[0] === a, 'attacker lost');
  });

  await run('losing battle', async () => {
    const a = add('flarewolf', P); const d = add('varga', E);
    await z.performAttack(a, d.uid);
    assert(s.players[P].lp === 2100, 'counter damage wrong: ' + s.players[P].lp);
    assert(!s.players[P].big[0], 'attacker still on field');
    assert(s.players[P].grave.length === 1, 'attacker not in grave');
    assert(s.players[E].big[0] === d, 'defender lost');
  });

  await run('tie battle', async () => {
    const a = add('flarewolf', P); const d = add('flarewolf', E);
    await z.performAttack(a, d.uid);
    assert(s.players[P].lp === 3000 && s.players[E].lp === 3000, 'tie caused damage');
    assert(!s.players[P].big[0] && !s.players[E].big[0], 'tie did not destroy both');
    assert(s.players[P].grave.length === 1 && s.players[E].grave.length === 1, 'tie grave issue');
  });

  await run('battle shield target', async () => {
    const a = add('varga', P); const d = add('golem', E);
    z.G.mod(d, { kind: 'battleShield', duration: 'nextOwner' });
    await z.performAttack(a, d.uid);
    assert(s.players[E].lp === 1600, 'shield damage wrong: ' + s.players[E].lp);
    assert(s.players[E].big[0] === d, 'shielded defender destroyed');
    assert(s.players[E].grave.length === 0, 'shielded defender in grave');
  });

  await run('battle shield attacker', async () => {
    const a = add('flarewolf', P); const d = add('varga', E);
    z.G.mod(a, { kind: 'battleShield', duration: 'nextOwner' });
    await z.performAttack(a, d.uid);
    assert(s.players[P].lp === 2100, 'attacker shield damage wrong: ' + s.players[P].lp);
    assert(s.players[P].big[0] === a, 'shielded attacker destroyed');
  });

  await run('validTargets taunt', async () => {
    const a = add('flarewolf', P); const d1 = add('golem', E, 'big', 0); const d2 = add('varga', E, 'big', 1);
    z.G.mod(d1, { kind: 'taunt', duration: 'nextOwner' });
    const info = z.validTargets(a);
    assert(info.monsters.length === 1 && info.monsters[0] === d1, 'taunt not enforced');
  });

  await run('twinblade direct bypass', async () => {
    const a = add('twinblade', P); add('varga', E);
    z.G.mod(a, { kind: 'direct', duration: 'end' });
    await z.performAttack(a, null);
    assert(s.players[E].lp === 1500, 'direct bypass damage wrong: ' + s.players[E].lp);
    assert(s.players[E].big[0], 'bypassed monster should remain');
  });

  await run('summon sickness', async () => {
    const a = add('varga', P, 'big', 0, 10);
    assert(z.canAttackNow(a), 'summoned monster should not attack');
  });

  await run('already attacked', async () => {
    const a = add('varga', P); a.attacked = true;
    assert(z.canAttackNow(a), 'attacked monster should not attack again');
  });

  await run('lethal direct', async () => {
    const a = add('varga', P);
    s.players[E].lp = 500;
    await z.performAttack(a, null);
    assert(s.players[E].lp === 0, 'lethal LP wrong: ' + s.players[E].lp);
    assert(s.over === true && s.result === 'win', 'win not detected');
  });

  return out;
}

