  z-index: 3;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 268px;
  gap: 14px;
  min-height: 0;
  padding: 0 18px;
}

}

.dot-you,
.dot-foe {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--gold);
}

.dot-foe { background: var(--red); }

