.action-bar {
  position: relative;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 5px 12px;
  min-height: 62px;
  padding: 7px 11px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background:
    linear-gradient(90deg, rgba(14, 23, 44, 0.92), rgba(7, 12, 24, 0.8)),
    radial-gradient(ellipse at 0% 50%, rgba(232, 195, 122, 0.04), transparent 55%);
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.32);
  backdrop-filter: blur(10px);
}

.ab-info {
  flex: 1 1 320px;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.ab-kicker {
  font-size: 5.5px;
  letter-spacing: 0.18em;
  color: var(--gold);
  text-transform: uppercase;
}

.ab-kicker.target {
  color: #ff8792;
  animation: blink 1.2s infinite;
}

.ab-kicker.foe {
  color: #ff8792;
}

.ab-name {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: 0.03em;
}

.ab-meta {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 7.5px;
  color: var(--muted);
}

.ab-act {
  margin: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 8px;
  color: #aebcda;
}

.ab-act b {
  color: var(--gold);
  font-weight: 700;
}

.ab-actions {
  flex: 0 0 auto;
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 5px;
}

.ab-note {
