    assert(!s.players[E].big[0], 'defender still on field');
    assert(s.players[E].grave.length === 1, 'defender not in grave');
    assert(s.players[P].big[0] === a, 'attacker lost');
  });

  await run('losing battle', async () => {
    const a = add('flarewolf', P); const d = add('varga', E);
